// HasVehicleType applies the HasEdge predicate on the "vehicle_type" edge.
func HasVehicleType() predicate.CarpoolSession {
	return predicate.CarpoolSession(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, VehicleTypeTable, VehicleTypeColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasVehicleTypeWith applies the HasEdge predicate on the "vehicle_type" edge with a given conditions (other predicates).
func HasVehicleTypeWith(preds ...predicate.CarpoolVehicleType) predicate.CarpoolSession {
	return predicate.CarpoolSession(func(s *sql.Selector) {
		step := newVehicleTypeStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

