// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CarpoolSession) predicate.CarpoolSession {
	return predicate.CarpoolSession(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CarpoolSession) predicate.CarpoolSession {
	return predicate.CarpoolSession(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CarpoolSession) predicate.CarpoolSession {
	return predicate.CarpoolSession(sql.NotPredicates(p))
}
